import json, sys

raw = json.load(sys.stdin)
data = json.loads(raw['result'])
exps = data['data']['experiments']

# Classify experiments
analysis_exps = []  # CKA, gradient analysis - no eval needed
training_exps = []  # training-only, eval in separate _eval exp
eval_exps = []      # _eval experiments or combined train+eval

for eid, e in sorted(exps.items()):
    conclusion = e.get('conclusion','?')
    status = e.get('status','?')
    if conclusion not in ('success', 'negative'):
        continue

    metrics = e.get('metrics', {})
    spec = e.get('spec', {})

    # Determine experiment type
    is_analysis = eid in ('cka_analysis', 'cka_detach_ln', 'cka_random_occ', 'gradient_analysis', 'gradient_analysis_mixed_seed')
    is_eval_exp = '_eval' in eid

    # Check if it has eval results (CAR/TSR at top-level or in at_50000_50r)
    has_car = any(k.lower() in ('car', 'overall_car') for k in metrics.keys())
    has_at_50k_50r = 'at_50000_50r' in metrics
    has_at_50k_20r = 'at_50000_20r' in metrics
    has_at_47k_50r = 'at_47500_50r' in metrics
    has_eval = has_car or has_at_50k_50r or has_at_50k_20r or has_at_47k_50r

    # Rollout count
    rollouts = metrics.get('eval_rollouts', None)
    if has_at_50k_50r:
        at50k = metrics['at_50000_50r']
        if isinstance(at50k, dict) and 'total_episodes' in at50k:
            rollouts_from_at = at50k['total_episodes'] // 10  # 10 tasks
            if rollouts is None:
                rollouts = rollouts_from_at
    if rollouts is None and has_car:
        te = metrics.get('total_episodes', None)
        if te:
            rollouts = te // 10

    # Per-task check
    per_task = metrics.get('per_task', {})
    per_task_tsr = metrics.get('per_task_tsr', {})
    per_task_car = metrics.get('per_task_car', {})
    has_per_task = (isinstance(per_task, dict) and len(per_task) >= 10) or \
                   (isinstance(per_task_tsr, dict) and len(per_task_tsr) >= 10)
    # Also check at_50000_50r for per_task
    if has_at_50k_50r and isinstance(metrics['at_50000_50r'], dict):
        at50k_pt = metrics['at_50000_50r'].get('per_task', {})
        if isinstance(at50k_pt, dict) and len(at50k_pt) >= 10:
            has_per_task = True

    # Checkpoint step
    ckpt_step = metrics.get('checkpoint_step', None)
    if ckpt_step is None:
        ckpt_path = spec.get('checkpoint_path', '') if spec else ''
        if '50000' in str(ckpt_path):
            ckpt_step = 50000
        elif '47500' in str(ckpt_path):
            ckpt_step = 47500

    # Overall CAR/TSR
    car = metrics.get('CAR', metrics.get('car', metrics.get('overall_car', None)))
    tsr = metrics.get('TSR', metrics.get('tsr', metrics.get('overall_tsr', None)))
    if has_at_50k_50r and isinstance(metrics['at_50000_50r'], dict):
        if car is None:
            car = metrics['at_50000_50r'].get('CAR')
        if tsr is None:
            tsr = metrics['at_50000_50r'].get('TSR')

    info = {
        'eid': eid,
        'conclusion': conclusion,
        'car': car,
        'tsr': tsr,
        'rollouts': rollouts,
        'ckpt_step': ckpt_step,
        'has_per_task': has_per_task,
        'has_at_50k_50r': has_at_50k_50r,
        'has_at_50k_20r': has_at_50k_20r,
        'has_at_47k_50r': has_at_47k_50r,
        'has_eval': has_eval,
        'is_analysis': is_analysis,
        'is_eval_exp': is_eval_exp,
    }

    if is_analysis:
        analysis_exps.append(info)
    elif has_eval:
        eval_exps.append(info)
    else:
        training_exps.append(info)

print('=== ANALYSIS EXPERIMENTS (no eval needed) ===')
for e in analysis_exps:
    print(f\"  {e['eid']} ({e['conclusion']})\")

print(f\"\\n=== TRAINING-ONLY EXPERIMENTS (no eval in this record) ===  count={len(training_exps)}\")
for e in training_exps:
    # Check if corresponding _eval exists
    base = e['eid']
    eval_ids = [x['eid'] for x in eval_exps if x['eid'].startswith(base)]
    has_eval_record = len(eval_ids) > 0
    print(f\"  {e['eid']} ({e['conclusion']}) | has_eval_record={has_eval_record} eval_ids={eval_ids}\")

print(f\"\\n=== EXPERIMENTS WITH EVAL DATA ===  count={len(eval_exps)}\")
for e in eval_exps:
    flags = []
    if e['rollouts'] == 50: flags.append('50r')
    elif e['rollouts'] == 20: flags.append('20r')
    elif e['rollouts']: flags.append(f\"{e['rollouts']}r\")
    else: flags.append('?r')

    if e['has_per_task']: flags.append('per_task')
    else: flags.append('NO_per_task')

    if e['has_at_50k_50r']: flags.append('at50k50r')
    if e['has_at_50k_20r']: flags.append('at50k20r')
    if e['has_at_47k_50r']: flags.append('at47k50r')
    if e['ckpt_step']: flags.append(f'ckpt={e[\"ckpt_step\"]}')

    print(f\"  {e['eid']} ({e['conclusion']}) | CAR={e['car']} TSR={e['tsr']} | {' '.join(flags)}\")
"

