import json, sys

raw = json.load(sys.stdin)
data = json.loads(raw['result'])
exps = data['data']['experiments']

# For every experiment with eval data, determine: eval checkpoint step, eval rollout count
print('=== COMPREHENSIVE EVAL AUDIT ===')
print()

# Group experiments by condition
conditions = {
    'Full OCC': {
        's0': {'train': 'mvp_occ_s0', 'eval': None},
        's1': {'train': 'occ_s1_fresh', 'eval': ['occ_s1_fresh_eval_47500', 'occ_s1_fresh_eval_50000']},
        's2': {'train': 'mvp_occ_s2', 'eval': None},
    },
    'Vanilla': {
        's0': {'train': 'mvp_vanilla_s0', 'eval': None},
        's1': {'train': 'mvp_vanilla_s1', 'eval': None},
        's2': {'train': 'mvp_vanilla_s2', 'eval': None},
    },
    'Detach': {
        's0': {'train': 'ablation_occ_detach_s0', 'eval': None},
        's1': {'train': 'ablation_occ_detach_s1', 'eval': None},
        's2': {'train': 'ablation_occ_detach_s2', 'eval': 'ablation_occ_detach_s2_eval'},
    },
    'Random OCC': {
        's0': {'train': 'ablation_random_occ_s0', 'eval': None},
        's1': {'train': 'ablation_random_occ_s1', 'eval': None},
        's2': {'train': 'ablation_random_occ_s2', 'eval': 'ablation_random_occ_s2_eval'},
    },
    'cutoff_15k': {
        's0': {'train': 'cutoff_15k_s0', 'eval': 'cutoff_15k_s0_eval'},
    },
    'cutoff_25k': {
        's0': {'train': 'cutoff_25k_s0', 'eval': 'cutoff_25k_s0_eval'},
        's1': {'train': 'cutoff_25k_s1', 'eval': 'cutoff_25k_s1_eval'},
    },
    'cutoff_35k': {
        's0': {'train': 'cutoff_s0', 'eval': 'cutoff_s0_eval'},
        's1': {'train': 'cutoff_s1', 'eval': 'cutoff_s1_eval'},
        's2': {'train': 'cutoff_s2_v2', 'eval': 'cutoff_s2_v2_eval'},
    },
    'cutoff_45k': {
        's0': {'train': 'cutoff_45k_s0', 'eval': 'cutoff_45k_s0_eval'},
    },
    'reverse_cutoff': {
        's0': {'train': 'reverse_cutoff_s0', 'eval': 'reverse_cutoff_s0_eval'},
        's1': {'train': 'reverse_cutoff_s1', 'eval': 'reverse_cutoff_s1_eval'},
    },
    'Detach+LN': {
        's0': {'train': 'detach_ln_s0', 'eval': 'detach_ln_s0_eval'},
        's1': {'train': 'detach_ln_s1', 'eval': 'detach_ln_s1_eval'},
        's2': {'train': 'detach_ln_s2', 'eval': 'detach_ln_s2_eval'},
    },
    'Depth': {
        's0': {'train': 'depth_s0', 'eval': 'depth_s0_eval'},
        's1': {'train': 'depth_s1', 'eval': 'depth_s1_eval'},
        's2': {'train': 'depth_s2', 'eval': None},
        's3': {'train': 'depth_s3', 'eval': None},
    },
    'Vanilla retrain': {
        's0': {'train': 'vanilla_retrain_s0', 'eval': 'vanilla_retrain_s0_eval'},
    },
    'Full OCC retrain': {
        's0': {'train': 'full_occ_retrain_s0', 'eval': None},
    },
}

def get_eval_info(eid):
    if eid not in exps:
        return None
    e = exps[eid]
    m = e.get('metrics', {})
    s = e.get('spec', {})

    # Get CAR/TSR
    car = m.get('CAR', m.get('car', m.get('overall_car')))
    tsr = m.get('TSR', m.get('tsr', m.get('overall_tsr')))

    # Rollouts
    rollouts = m.get('eval_rollouts')
    te = m.get('total_episodes')
    if rollouts is None and te:
        rollouts = te // 10
    if rollouts is None:
        cmd = s.get('command', '') if s else ''
        if '--num_rollouts 50' in cmd:
            rollouts = 50

    # Checkpoint step
    ckpt = m.get('checkpoint_step')
    if ckpt is None:
        cp = s.get('checkpoint_path', '') if s else ''
        if '50000' in cp:
            ckpt = 50000
        elif '47500' in cp:
            ckpt = 47500

    # Per-task
    pt = m.get('per_task', {})
    pt_tsr = m.get('per_task_tsr', {})
    has_pt = (isinstance(pt, dict) and len(pt) >= 10) or (isinstance(pt_tsr, dict) and len(pt_tsr) >= 10)

    # at_50000_50r
    at50k50r = m.get('at_50000_50r')
    has_at50k50r = at50k50r is not None
    if has_at50k50r and isinstance(at50k50r, dict):
        if car is None:
            car = at50k50r.get('CAR')
        if tsr is None:
            tsr = at50k50r.get('TSR')
        at_pt = at50k50r.get('per_task', {})
        if isinstance(at_pt, dict) and len(at_pt) >= 10:
            has_pt = True
        if rollouts is None:
            te2 = at50k50r.get('total_episodes')
            if te2:
                rollouts = te2 // 10

    return {
        'car': car, 'tsr': tsr, 'rollouts': rollouts,
        'ckpt': ckpt, 'has_pt': has_pt, 'has_at50k50r': has_at50k50r,
        'has_metrics': bool(m)
    }

for cond, seeds in conditions.items():
    print(f'--- {cond} ---')
    for seed, info in seeds.items():
        train_id = info['train']
        eval_ids = info['eval']

        # Check train record for eval data
        train_eval = get_eval_info(train_id)

        # Check eval records
        eval_infos = []
        if eval_ids:
            if isinstance(eval_ids, str):
                eval_ids = [eval_ids]
            for eid in eval_ids:
                ei = get_eval_info(eid)
                if ei:
                    eval_infos.append((eid, ei))

        # Determine best eval source
        best = None
        best_source = None

        # Check train record first
        if train_eval and (train_eval['car'] is not None or train_eval['has_at50k50r']):
            best = train_eval
            best_source = train_id

        # Check eval records
        for eid, ei in eval_infos:
            if ei['car'] is not None:
                if best is None or (ei['has_pt'] and not best['has_pt']):
                    best = ei
                    best_source = eid

        if best is None:
            if train_eval and not train_eval['has_metrics']:
                print(f'  {seed}: NO EVAL (training only: {train_id})')
            else:
                print(f'  {seed}: NO EVAL DATA ({train_id})')
        else:
            flags = []
            flags.append(f'{best[\"rollouts\"]}r' if best['rollouts'] else '?r')
            flags.append('PT:YES' if best['has_pt'] else 'PT:NO')
            flags.append(f'ckpt={best[\"ckpt\"]}' if best['ckpt'] else 'ckpt=?')
            flags.append('at50k50r' if best['has_at50k50r'] else 'no_at50k50r')
            print(f'  {seed}: CAR={best[\"car\"]} TSR={best[\"tsr\"]} | {\" \".join(flags)} | src={best_source}')
    print()
